    bucket = capacity
    denied_count = 0
    result = []
    for v in events:
        refill = base_refill + denied_count
        bucket = min(bucket + refill, capacity)
        if bucket >= v:
            bucket -= v
            result.append(v)
        else:
            denied_count += 1
